const fp=x=>String(x).replace('.',lang==='uk'?',':'.'),cur=()=>lang==='uk'?'грн':'UAH',un=p=>p.u==='m'?(lang==='uk'?'м':'m'):(lang==='uk'?'шт':'pc'),lov=p=>p.v.reduce((a,b)=>+b[1]<+a[1]?b:a)[1],sz=v=>Array.isArray(v[0])?v[0][lang==='uk'?0:1]:v[0];
